小規模校では、1学年が1学級（10〜20人台）のところもあります。大規模な学校と小規模な学校のどちらが良いかは、一概には言えません。大きい学校は友達や行事、部活動などの選択肢が広がりやすく、小さい学校は先生の目が行き届きやすい、といった違いがあります。

