    body: `
会社員の給料から毎月引かれている「住民税」の市の分が、個人市民税です。この記事では、船橋市の個人市民税について、何人が納めていて、1人あたりいくらか、所得はどう変わってきたのかを、市の公式資料（令和8年度 市税概要）でまとめました。

**令和7年度：納税義務者は36.1万人、1人あたり約14.4万円**

個人市民税（現年度分）の納税義務者※1は、令和7年度に**361,331人**、調定額（納めるべきとして決められた額）は**520.3億円**で、1人あたりは**143,986円**でした。

| 年度 | 納税義務者 | 調定額（現年度分） | 1人あたり |
|---|---|---|---|
| 令和4年度 | 343,224人 | 465.4億円 | 135,599円 |
| 令和5年度 | 347,394人 | 477.1億円 | 137,346円 |
| 令和6年度 | 353,557人 | 459.3億円 | 129,903円 |
| 令和7年度 | 361,331人 | 520.3億円 | 143,986円 |

[[CHART:indiv-tax-per-person]]

納税義務者は、4年間で5.3%増えました。1人あたりの額は、令和6年度に前年度比5.4%減り、令和7年度に10.8%増えています。令和6年度は、均等割の引き下げ（市民税が年3,500円から3,000円に。あわせて国税の森林環境税が年1,000円課されるようになりました）や、所得割の減少が重なった年です（税収全体の動きは、[税収（市税）の記事](/articles/funabashi-city-tax-revenue-guide)をご覧ください）。

**所得は、10年で約17%増えた**

所得割※2の納税義務者の、1人あたりの総所得額は、平成28年度の約347万円から、令和8年度（令和7年中の所得）の約407万円まで、10年で**約17%増えました**。納税義務者の数も、30.2万人から34.9万人に増えています。

[[CHART:indiv-income-per-person]]

ただし、令和6年度は、納税義務者数が前後の年より少なく（32.1万人）、1人あたりの所得が高く出ています。この年だけ、数え方が他の年と違う可能性があるため、10年の傾向を見るときの参考にとどめてください。なお、別の記事で紹介している平均所得（令和5年度で389万円）は、総務省の統計の「課税対象所得」です。市の資料の「総所得額」（令和5年度は約374万円）とは、集計の範囲が違うため、数字が一致しません（[平均所得の記事](/articles/average-income-guide)）。

**所得の種類別：給与所得者が8割**

令和8年度の当初課税で、所得割の納税義務者を、所得の種類別に見ると、次のとおりです。

| 区分 | 納税義務者 | 構成比 | 1人あたり総所得額 |
|---|---|---|---|
| 給与所得者 | 285,361人 | 81.8% | 約426万円 |
| 営業所得者 | 10,771人 | 3.1% | 約425万円 |
| 農業所得者 | 108人 | 0.0% | 約522万円 |
| その他（年金など） | 45,543人 | 13.1% | 約236万円 |
| 譲渡所得者 | 7,149人 | 2.0% | 約667万円 |
| 合計 | 348,932人 | 100.0% | 約407万円 |

**所得階層別：人数の半分は、税額の2割**

令和8年度の所得割を、課税標準額（所得から控除を引いた額）の段階別に見ると、人数と税額の割合に、差が出ます。

| 課税標準額 | 納税義務者の構成比 | 所得割額の構成比 |
|---|---|---|
| 200万円以下 | 50.8% | 18.3% |
| 200万円超〜300万円以下 | 18.5% | 16.2% |
| 300万円超〜400万円以下 | 11.0% | 13.5% |
| 400万円超〜550万円以下 | 8.6% | 14.3% |
| 550万円超〜700万円以下 | 3.7% | 8.1% |
| 700万円超〜1,000万円以下 | 3.2% | 9.2% |
| 1,000万円超 | 2.2% | 13.2% |
| 分離課税者 | 2.0% | 7.2% |

納税義務者の約半分（50.8%）は、課税標準額が200万円以下で、所得割額の割合は18.3%です。一方、1,000万円を超える2.2%の人が、所得割額の13.2%を占めています。

**納め方：3分の2は給与天引き**

令和7年度の納税義務者を、納め方別に見ると、会社の給与から天引きされる「特別徴収※3」が242,772人（67.2%）、自分で納める「普通徴収」が77,838人（21.5%）、年金から天引きされる「年金特徴」が40,721人（11.3%）です。

**筆者の見解：「平均」の裏にある、人数と税額のずれ**

「1人あたり14万円」は平均で、実際には、人によって大きく違います。所得階層別の表を見ると、納税義務者の半分は低めの階層で、税額の多くは、中・高所得の人が負担しています。個人市民税は、人数の多い層だけでなく、所得の高い層の収入の動きにも左右される税だと分かります。

令和7年度に、個人市民税が前年度比+13.1%と大きく増えたのも、所得の動きに加えて、前年度の特殊な要因（定額減税など）の反動が重なったためと考えられます。1年の数字だけで「増えた」「減った」と見るのではなく、数年の流れで見るのが安全です。（この節は編集部の見解で、公式の見解ではありません。）

**できること**

毎年6月ごろに届く「市民税・県民税 特別徴収税額の決定・変更通知書」（会社員の方）や、納税通知書（個人事業主・年金の方など）を、一度見て、ご自身が納めている額を確認してみてください。

**この記事の限界について**

数字は、市の「令和8年度 市税概要」にある値です。令和8年度の所得割は当初課税額（令和7年中の所得に対する、令和8年度の課税）です。令和6年度は、前後の年と数え方が異なる可能性があります。所得階層別の表の「課税標準額」は、収入（年収）ではなく、所得から各種の控除を引いたあとの額です。

**言葉の説明**

- ※1　納税義務者：税金を納める義務のある人のことです。個人市民税では、前年に収入があった人のうち、課税される人を指します。
- ※2　所得割：所得に応じて決まる、個人市民税の部分のことです。均等割は、所得に関係なく、一律でかかる部分です。
- ※3　特別徴収：会社が、従業員の給与から住民税を天引きして、市に納める方法のことです。

**出典**

- 船橋市「令和8年度 市税概要」（令和8年7月1日現在）：[船橋市公式サイト（PDF）](https://www.city.funabashi.lg.jp/kurashi/zei/001/01/p000001_d/fil/shizeigaiyou.pdf)
- 船橋市「税額の計算方法概要図」（均等割額の変更）：[船橋市公式サイト](https://www.city.funabashi.lg.jp/kurashi/zei/007/003/p000866.html)
- 1人あたりの額、増加率、構成比の差は、上記の資料をもとに、筆者が計算したものです。
    `.trim()
